}

#[tokio::test]
async fn test_storage() {
    let temp_dir = tempfile::tempdir().unwrap();
    let path = temp_dir.path().join("test.json");
    let storage = storage::Storage::new(path.to_str().unwrap().to_string()).unwrap();

    let page = storage::CrawledPage {
        url: "https://example.com".into(),
        title: "Test".into(),
        content: "Content".into(),
        links: vec![],
        depth: 0,
        timestamp: chrono::Utc::now(),
    };

    storage.save_page(page).await;
    storage.persist().await.unwrap();

    let visited = storage.get_visited().await;
    assert!(visited.contains(&"https://example.com".to_string()));
}
